_ASSETS = {
    "logo": LOGO_B64,
    "emblema": EMBLEMA_B64,
    "favicon": FAVICON_B64,
}


def data_uri(nome: str) -> str:
    """URI embutida para usar direto no atributo src de uma <img>."""
    dados = _ASSETS.get(nome, "")
    return f"data:image/png;base64,{dados}" if dados else ""


def favicon_image():
    """Favicon como imagem PIL — formato que o set_page_config aceita.

    Devolve None se o Pillow não estiver disponível, para o chamador cair no
    emoji de reserva em vez de quebrar a página.
    """
    try:
        from PIL import Image

        return Image.open(io.BytesIO(base64.b64decode(FAVICON_B64)))
    except Exception:  # pragma: no cover - reserva defensiva
        return None
